package dev.bennett.codexmeter;
import android.app.*;import android.content.*;import android.content.res.Configuration;import android.graphics.*;import android.os.Bundle;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import org.json.*;

/** Existing emulator only; detached fake account, same production UI/SQLite paths. */
public final class GrowthRebornNativeTest extends Instrumentation {
 int checks;android.content.Context c;GrowthActivity a;String account;Throwable error;
 void check(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 void main(Runnable r){runOnMainSync(()->{try{r.run();}catch(Throwable e){error=e;}});if(error!=null)throw new AssertionError(error);waitForIdleSync();}
 JSONObject state()throws Exception{return RpgProgressStore.export(c,account).getJSONObject("rpg");}
 void ready()throws Exception{for(int i=0;i<100;i++){Thread.sleep(60);boolean[] ok={false};main(()->{try{java.lang.reflect.Field busy=GrowthActivity.class.getDeclaredField("busy");busy.setAccessible(true);ok[0]=!busy.getBoolean(a)&&a.findViewById(R.id.dashboard_scroll).findViewWithTag("journey:switch")!=null;}catch(Exception e){throw new RuntimeException(e);}});if(ok[0])return;}throw new AssertionError("Growth timeout");}
 androidx.appcompat.widget.SwitchCompat toggle(boolean titles){return a.findViewById(R.id.dashboard_scroll).findViewWithTag(titles?"titles:switch":"journey:switch");}
 void token(long n)throws Exception{long now=System.currentTimeMillis();RpgProgressStore.tokens(c,account,new JSONObject().put("account",account).put("source","codex_account_usage_v1").put("at",now).put("summary",new JSONObject().put("lifetimeTokens",n)));}
 @Override public void onCreate(Bundle b){super.onCreate(b);start();}
 @Override public void onStart(){Bundle result=new Bundle();try{
  c=getTargetContext();check(c.getPackageName().endsWith(".rpg3qa"),"Only isolated emulator fixture");AppPreferences.setAutomaticRefresh(c,false);UpdatePreferences.setAutomaticChecks(c,false);long now=System.currentTimeMillis();SecureTokenStore.save(c,new AuthTokens("REBORN_QA_FAKE_ACCESS","REBORN_QA_FAKE_REFRESH","",now+86400000,"reborn-synthetic-"+UUID.randomUUID(),""));account=SubscriptionStore.accountKey(c);AppPreferences.saveSnapshot(c,new UsageSnapshot("pro",true,false,null,new UsageWindow(40,604800,0,(now+86400000)/1000),now));
  // Legacy v28 journal has no opt-in fields. No fake records enter any user package.
  JSONObject old=AccountProgress.empty();old.getJSONObject("tier").put("tier",7).put("highest",7);RpgEngine.ingestOfficial(old,account,new JSONObject().put("account",account).put("source","codex_account_usage_v1").put("at",now).put("summary",new JSONObject().put("lifetimeTokens",100_000_000)),now);List<String> legacy=RpgGrowthFacts.earned(RpgEngine.state(old));long xp=RpgEngine.state(old).getLong("xp");check(!legacy.isEmpty(),"Old automatic awards reproduced");try(android.database.sqlite.SQLiteDatabase db=android.database.sqlite.SQLiteDatabase.openOrCreateDatabase(c.getDatabasePath(RpgProgressStore.NAME),null)){db.execSQL("INSERT OR REPLACE INTO profiles(account,document) VALUES(?,?)",new Object[]{account,old.toString()});}
  JSONObject s=state();check(s.getLong("xp")==xp,"Legacy migration keeps XP");check(s.getJSONObject("KR").getInt("highest")==7,"Legacy best tier preserved");check(!AchievementJourney.enabled(s)&&!TitleJourney.enabled(s),"Both new journeys default OFF");check(RpgGrowthFacts.earned(s).isEmpty(),"New codex starts empty");check(TitleJourney.owned(s).containsAll(legacy),"Old titles preserved");check(AchievementJourney.journey(s).getJSONObject("legacy").getJSONObject("achievements").length()==53,"All old definitions archived");
  a=(GrowthActivity)startActivitySync(new Intent(c,GrowthActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready();
  main(()->{Configuration conf=new Configuration(a.getResources().getConfiguration());conf.setLocale(java.util.Locale.KOREAN);a.getResources().updateConfiguration(conf,a.getResources().getDisplayMetrics());a.load(true);});Thread.sleep(200);ready();
  for(boolean titles:new boolean[]{false,true}){main(()->{toggle(titles).performClick();check(a.detailDialog!=null&&a.detailDialog.isShowing(),"Real start confirmation");check(!toggle(titles).isChecked(),"No activation before confirmation");shot(titles?"title-start.png":"achievement-start.png",a.detailDialog.getWindow().getDecorView(),360,600);a.detailDialog.getButton(-2).performClick();});Thread.sleep(200);ready();check((titles?TitleJourney.journey(state()):AchievementJourney.journey(state())).optLong("first_started_at")==0,"Cancel does not write start");}
  main(()->toggle(true).performClick());main(()->a.detailDialog.getButton(-1).performClick());Thread.sleep(250);ready();token(101_000_000);s=state();check(!AchievementJourney.enabled(s)&&TitleJourney.enabled(s),"OFF / ON independent state");check(RpgGrowthFacts.earned(s).isEmpty(),"Title-only activity cannot earn medals");check(TitleJourney.journey(s).getJSONObject("facts").getJSONObject("tokens_1000000").getBoolean("unlocked"),"Title-only verified new token condition unlocks");
  main(()->toggle(false).performClick());main(()->a.detailDialog.getButton(-1).performClick());Thread.sleep(250);ready();token(201_000_000);s=state();check(AchievementJourney.enabled(s)&&TitleJourney.enabled(s),"ON / ON state");check(RpgGrowthFacts.earned(s).size()==3,"Only fresh 100m delta earns three medals");List<String> medals=new ArrayList<>(RpgGrowthFacts.earned(s));check(RpgShowcase.save(c,account,medals,s),"Three showcase medals stored");
  main(()->a.load(true));Thread.sleep(250);ready();main(()->toggle(true).performClick());Thread.sleep(250);ready();check(AchievementJourney.enabled(state())&&!TitleJourney.enabled(state()),"ON / OFF independent pause");main(()->toggle(false).performClick());Thread.sleep(250);ready();check(!AchievementJourney.enabled(state())&&!TitleJourney.enabled(state()),"OFF / OFF after pause");check(RpgGrowthFacts.earned(state()).equals(medals),"Pausing retains earned medals");
  JSONObject journal=RpgProgressStore.export(c,account);for(int width:new int[]{320,360,411})for(float font:new float[]{1f,1.5f})for(java.util.Locale locale:new java.util.Locale[]{java.util.Locale.KOREAN,java.util.Locale.ENGLISH}){main(()->{Configuration conf=new Configuration(a.getResources().getConfiguration());conf.screenWidthDp=width;conf.fontScale=font;conf.setLocale(locale);a.getResources().updateConfiguration(conf,a.getResources().getDisplayMetrics());a.load(true);});Thread.sleep(200);ready();main(()->{
   String key=width+"-"+font+"-"+locale.getLanguage();shot("growth-"+key+".png",a.findViewById(R.id.dashboard_scroll),width,900);for(String kind:new String[]{"KR","WORLD","level","plan"}){View card=a.findViewById(R.id.dashboard_scroll).findViewWithTag("growth:"+kind);check(card!=null&&card.isClickable(),"Real profile card remains clickable");card.performClick();check(a.detailDialog!=null&&a.detailDialog.isShowing(),"Real detail opens");shot(kind+"-"+key+".png",RpgDetails.body(a,kind,journal.optJSONObject("rpg"),true),width,1050);a.detailDialog.dismiss();}
   View archive=a.findViewById(R.id.dashboard_scroll).findViewWithTag("growth:archive");archive.performClick();check(a.detailDialog!=null&&a.detailDialog.isShowing(),"Read-only archive opens through real button");shot("archive-"+key+".png",a.detailDialog.getWindow().getDecorView(),width,1050);a.detailDialog.dismiss();
   shot("medal-"+key+".png",RpgMedalUi.body(a,journal.optJSONObject("rpg"),RpgGrowthFacts.entry(medals.get(0)),true),width,1000);
  });}
  main(()->{a.finish();});a=(GrowthActivity)startActivitySync(new Intent(c,GrowthActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready();check(RpgGrowthFacts.earned(state()).equals(medals),"Reopen preserves earned medals");check(RpgShowcase.selected(c,state()).equals(medals),"Reopen preserves ordered showcase");main(()->a.finish());
  result.putString("stream","Growth Reborn native: "+checks+" checks passed; synthetic account / existing emulator, no Samsung phone proof.\n");finish(-1,result);
 }catch(Throwable e){StringWriter w=new StringWriter();e.printStackTrace(new PrintWriter(w));result.putString("stream",w.toString());finish(0,result);}}
 void shot(String name,View view,int width,int height){try{int w=Ui.dp(c,width),h=Ui.dp(c,height);view.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.AT_MOST));view.layout(0,0,w,view.getMeasuredHeight());Bitmap bitmap=Bitmap.createBitmap(w,Math.max(1,view.getMeasuredHeight()),Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.drawColor(0xff0d0e10);view.draw(canvas);File folder=new File(c.getExternalFilesDir(null),"reborn-fixtures");folder.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(folder,name))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}bitmap.recycle();}catch(Exception e){throw new RuntimeException(e);}}
}
